-  return listItem(item);
-}
+const RENDERERS = {
+  legacy:  renderLegacy,
+  email:   emailRow,
+  preview: previewItem,
+  list:    listItem,
+};
+function render(item, mode /* 'legacy'|'email'|'preview'|'list' */) {
+  return RENDERERS[mode](item);
+}
